"""Standalone reader page kept outside the translation dashboard template."""
from __future__ import annotations
import json


def reader_page(job_id: str) -> str:
    encoded = json.dumps(job_id)
    return f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مطالعهٔ کتاب | J Book Translate</title><style>
:root{{--app:#f2f5f9;--surface:#fff;--text:#202936;--muted:#697689;--accent:#536fa7;--line:#e2e7ee;--font-size:18px;--line-height:1.9;--reading-width:760px}}*{{box-sizing:border-box}}body{{margin:0;background:var(--app);color:var(--text);font:15px Vazirmatn,Segoe UI,Tahoma,sans-serif}}body.study-night{{--app:#17191d;--surface:#22252b;--text:#d8d2c8;--muted:#aaa69f;--accent:#b8a477;--line:#343941}}button,select{{font:inherit;border:1px solid var(--line);background:var(--surface);color:var(--text);border-radius:8px;padding:8px 10px}}button:focus-visible,select:focus-visible{{outline:3px solid var(--accent);outline-offset:2px}}.bar{{position:sticky;top:0;z-index:2;display:flex;gap:8px;align-items:center;justify-content:space-between;padding:12px max(18px,calc((100vw - var(--reading-width))/2));background:var(--surface);border-bottom:1px solid var(--line)}}.bar strong{{font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}.controls{{display:flex;gap:7px;align-items:center;flex-wrap:wrap}}.layout{{max-width:1100px;margin:0 auto;display:grid;grid-template-columns:220px minmax(0,1fr);gap:28px;padding:28px 18px 70px}}.toc{{position:sticky;top:72px;align-self:start;max-height:calc(100vh - 100px);overflow:auto}}.toc button{{display:block;width:100%;text-align:right;border:0;background:transparent;padding:9px;color:var(--muted)}}.toc button.active{{color:var(--accent);font-weight:700;background:color-mix(in srgb,var(--accent) 10%,transparent)}}.book{{width:min(100%,var(--reading-width));justify-self:center;background:var(--surface);padding:clamp(25px,6vw,62px);border-radius:14px;min-height:70vh}}.book h1{{font-size:1.55em;line-height:1.5;margin:0 0 1.7em}}.content{{font-size:var(--font-size);line-height:var(--line-height)}}.content p,.content div{{margin:0 0 1.15em}}.content blockquote{{margin:1.4em 0;padding:0 1em;border-inline-start:3px solid var(--accent);color:var(--muted)}}.content a{{color:var(--accent)}}.content img{{max-width:100%;height:auto}}.status{{color:var(--muted);font-size:13px}}@media(max-width:760px){{.layout{{display:block;padding:16px 10px}}.toc{{position:static;display:flex;overflow:auto;max-height:none;margin-bottom:12px}}.toc button{{white-space:nowrap;width:auto}}.book{{padding:25px 20px;border-radius:10px}}.bar{{padding:10px}}}}
</style></head><body><header class="bar"><strong id="title">در حال بازکردن کتاب…</strong><div class="controls"><button id="night" aria-pressed="false">حالت شب مطالعه</button><select id="font" aria-label="اندازهٔ متن"><option value="16">متن کوچک</option><option value="18">متن معمولی</option><option value="20">متن بزرگ</option><option value="22">متن خیلی بزرگ</option></select><select id="leading" aria-label="فاصلهٔ خطوط"><option value="1.7">فشرده</option><option value="1.9">راحت</option><option value="2.1">باز</option></select><select id="width" aria-label="عرض متن"><option value="640">باریک</option><option value="760">استاندارد</option><option value="880">عریض</option></select><select id="direction" aria-label="جهت متن"><option value="auto">خودکار</option><option value="rtl">راست‌به‌چپ</option><option value="ltr">چپ‌به‌راست</option></select><button id="reset">بازنشانی</button></div></header><main class="layout"><nav class="toc" id="toc" aria-label="فهرست فصل‌ها"></nav><article class="book"><p class="status" id="status"></p><h1 id="chapter-title"></h1><section class="content" id="content"></section></article></main><script>
const jobId={encoded},$=s=>document.querySelector(s),defaults={{study_night_mode:false,reading_font_size:18,reading_line_height:1.9,reading_width:760,reading_direction:'auto'}},settings={{...defaults}},keys=Object.keys(defaults);let chapters=[];function apply(){{document.body.classList.toggle('study-night',!!settings.study_night_mode);document.documentElement.style.setProperty('--font-size',settings.reading_font_size+'px');document.documentElement.style.setProperty('--line-height',settings.reading_line_height);document.documentElement.style.setProperty('--reading-width',settings.reading_width+'px');$('#night').setAttribute('aria-pressed',!!settings.study_night_mode);$('#font').value=settings.reading_font_size;$('#leading').value=settings.reading_line_height;$('#width').value=settings.reading_width;$('#direction').value=settings.reading_direction}}async function save(extra={{}}){{Object.assign(settings,extra);apply();await fetch('/api/reader/settings',{{method:'PUT',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(settings)}})}}function directionFor(html){{if(settings.reading_direction!=='auto')return settings.reading_direction;return /[\u0600-\u06FF]/.test(html)?'rtl':'ltr'}}async function loadChapter(id){{try{{const r=await fetch(`/api/reader/${{jobId}}/chapters/${{id}}`);if(!r.ok)throw Error();const d=await r.json();$('#chapter-title').textContent=d.title;const content=$('#content');content.innerHTML=d.html;content.dir=directionFor(d.html);content.style.textAlign=content.dir==='rtl'?'right':'left';document.querySelectorAll('.toc button').forEach(b=>b.classList.toggle('active',Number(b.dataset.id)===id));await save({{reading_last_location:{{job_id:jobId,chapter:id}}}});$('#status').textContent=`فصل ${{id+1}} از ${{chapters.length}}`}}catch{{$('#status').textContent='خواندن این فصل ممکن نشد.'}}}}async function init(){{const [s,c]=await Promise.all([fetch('/api/reader/settings'),fetch(`/api/reader/${{jobId}}/chapters`)]);const sd=await s.json(),cd=await c.json();Object.assign(settings,sd.value||{{}});chapters=cd.items||[];apply();$('#title').textContent=cd.book||'کتاب ترجمه‌شده';$('#toc').innerHTML=chapters.map(x=>`<button data-id="${{x.id}}">${{x.title}}</button>`).join('');document.querySelectorAll('.toc button').forEach(b=>b.onclick=()=>loadChapter(Number(b.dataset.id)));const saved=settings.reading_last_location;if(chapters.length)loadChapter(saved&&saved.job_id===jobId?Math.min(saved.chapter,chapters.length-1):0)}}$('#night').onclick=()=>save({{study_night_mode:!settings.study_night_mode}});$('#font').onchange=e=>save({{reading_font_size:Number(e.target.value)}});$('#leading').onchange=e=>save({{reading_line_height:Number(e.target.value)}});$('#width').onchange=e=>save({{reading_width:Number(e.target.value)}});$('#direction').onchange=e=>save({{reading_direction:e.target.value}});$('#reset').onclick=()=>save({{...defaults}});init();
</script></body></html>'''
